    {
      "keystrokes": "grep -h healthz /var/log/webapp/access.log /var/log/webapp/access.log.1 | awk '{print $1, $6, $7}' | sort | uniq -c\n",
      "duration": 0.5
    },
    {
      "keystrokes": "which python3\n",
