{
  "analysis": "The config fails to source because of `DEST_DIR = /var/backups/app`. Since the config is tiny, rewriting it is simplest.",
  "plan": "Rewrite backup.conf with correct assignments, fix the two script bugs with sed, and show the results.",
  "commands": [
    {
      "keystrokes": "cat > backup.conf <<'EOF'\n# Backup settings, sourced by backup.sh\nSRC_DIR=/app/data\nDEST_DIR=/var/backups/app\nARCHIVE_NAME=app-data.tar.gz\nMANIFEST_GLOB=\"*.csv\"\nEOF\n",
