  "analysis": "Each record has sensor_id, site, status and a list of readings with t and value; some values are null. 12 sensors are 'ok' and 2 are 'offline', which must be excluded entirely.",
  "plan": "Rewrite report.py with an implementation of build_site_summary that filters status=='ok', skips null values, groups by site and returns sorted rows; keep write_csv as is. Then byte-compile to check syntax.",
  "commands": [
    {
      "keystrokes": "cat > /app/pipeline/report.py <<'EOF'
"""Site-level summary report."""
import csv
from collections import defaultdict

FIELDS = ["site", "sensors", "readings", "mean_value", "max_value"]


def build_site_summary(records):
    """Aggregate sensor records into one row per site.

    Only sensors with status "ok" are counted; null readings are ignored.
    """
    sensors = defaultdict(int)
    values = defaultdict(list)
    for rec in records:
        if rec.get("status") != "ok":
            continue
        site = rec["site"]
        sensors[site] += 1
        for r in rec.get("readings") or []:
            v = r.get("value")
            if v is None:
                continue
            values[site].append(float(v))
    rows = []
    for site in sorted(sensors):
        vals = values[site]
        rows.append({
            "site": site,
            "sensors": sensors[site],
            "readings": len(vals),
            "mean_value": sum(vals) / len(vals) if vals else 0.0,
            "max_value": max(vals) if vals else 0.0,
        })
    return rows


def write_csv(rows, path):
    with open(path, "w", newline="") as fh:
        w = csv.writer(fh)
        w.writerow(FIELDS)
        for r in rows:
            w.writerow([r["site"], r["sensors"], r["readings"],
                        f"{r['mean_value']:.2f}", f"{r['max_value']:.2f}"])
EOF
